import type { Register, SessionMeasureInput } from 'claude-code'

type Usage = Pick<SessionMeasureInput, 'context' | 'rateLimits' | 'cost'>

const LIMIT_NAMES: Record<string, string> = { five_hour: '5h', seven_day: '7d', spend_limit: 'spend' }

const k = (n: number) => (n >= 1000 ? `${Math.round(n / 1000)}k` : `${n}`)

export const formatUsage = ({ context, rateLimits, cost }: Usage): string => {
  const parts = [
    context.tokens === undefined
      ? `ctx –/${k(context.window)}`
      : `ctx ${k(context.tokens)}/${k(context.window)} (${context.percent ?? 0}%)`,
    ...rateLimits.map(r => `${LIMIT_NAMES[r.kind] ?? r.kind} ${r.percentUsed}%`),
  ]
  if (cost) parts.push(`$${cost.usd.toFixed(2)}`)
  return `◆ ${parts.join(' · ')}`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    $.ui.status(formatUsage(await $.session.usage()))
    return result
  })

  on('session.measure', ($, e, next) => {
    $.ui.status(formatUsage(e))
    return next(e)
  })
}

